<script module lang="ts">
/**
 * Slides shown one at a time, paged by the reader (`design/components/carousel.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/carousel.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/carousel'
import { useMachine } from '@zag-js/svelte'

import {
  Render,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/carousel.module.css'
import Button from '../controls/Button.svelte'

export interface CarouselSlide {
  id: string
  label: string
  content: Snippet | string
}

export interface CarouselProps {
  defaultIndex?: number
  /**
   * The current slide, controlled as in Slider; swiping also calls `onIndexChange`.
   */
  index?: number
  /**
   * Names the carousel, such as "Product tour" rather than "Carousel".
   */
  label: string
  /**
   * Wraps from the first slide to the last and back; when off, the end buttons are disabled.
   */
  loop?: boolean
  nextLabel: string
  onIndexChange?: (index: number) => void
  /**
   * Accessible names for the previous and next buttons, in the app's language, with no default.
   */
  previousLabel: string
  /**
   * Spoken role names for the region and each slide (default `carousel` and `slide`, the APG's
   * terms); localized hosts pass both or neither.
   */
  roleDescriptions?: { carousel: string; slide: string }
  /**
   * Slides in reading order; an empty list renders nothing, and the page handles it.
   */
  slides: CarouselSlide[]
}
</script>

<script lang="ts">
let {
  defaultIndex = 0,
  index,
  label: labelOwn,
  loop = false,
  nextLabel,
  onIndexChange,
  previousLabel,
  roleDescriptions = (() => ({ carousel: 'carousel', slide: 'slide' }))(),
  slides,
}: CarouselProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let kept = $state(index ?? defaultIndex)
let scrolls = $state(0)
let sent = $state(-1)
let moving = $state(false)
let controls = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
let viewport = $state<HTMLElement | null>(null)
const measurable = $derived(() => viewport !== null && viewport.clientWidth > 0)
const within = $derived((at: number) => Math.min(Math.max(at, 0), Math.max(slides.length - 1, 0)))
const shown = $derived(within(index ?? kept))
const instant = $derived(() => {
  const duration =
    viewport === null
      ? NaN
      : parseFloat(getComputedStyle(viewport).getPropertyValue('--pm-motion-duration-surface'))
  return Number.isNaN(duration) || duration <= 0
})
const travel = $derived((to: number) => {
  if (to === shown) return
  if (index === undefined) go(to, instant())
  else onIndexChange?.(to)
})
const resting = $derived(
  (nearest: number) =>
    viewport !== null &&
    Math.abs(Math.abs(viewport.scrollLeft) - nearest * viewport.clientWidth) <= 1,
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      slideCount: slides.length,
      defaultPage: index ?? defaultIndex,
      loop: loop,
      onPageChange: (details) => {
        measurable() &&
          details.page !== kept &&
          ((kept = details.page), details.page !== index && onIndexChange?.(details.page))
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const go = $derived((to: number, now: boolean) => {
  sent = scrolls
  moving = true
  api.scrollTo(to, now)
})
const settle = $derived(() => {
  if (viewport === null || !measurable()) return
  const nearest = within(Math.round(Math.abs(viewport.scrollLeft) / viewport.clientWidth))
  if (moving) {
    if (scrolls === sent || !resting(nearest)) return
    moving = false
  }
  if (nearest !== api.page) go(nearest, true)
})
const effect1 = () => {
  index !== undefined &&
    ((kept = within(index)), within(index) !== api.page && go(within(index), instant()))
}
watchEffect(effect1, { watch: () => index, mount: false })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    measurable() && api.page !== within(kept) && go(within(kept), true)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [viewport]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect2)
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const timer = setTimeout(() => {
    settle()
  }, 150)
  release3 = () => clearTimeout(timer)
}
watchEffect(effect3, { watch: () => scrolls, mount: false })
onDestroy(() => release3?.())
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const run = () => {
    viewport !== null &&
      viewport.getAttribute('tabindex') !== '0' &&
      viewport.setAttribute('tabindex', '0')
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [viewport])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['tabindex'],
      })
  release4 = () => {
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect4)
onDestroy(() => release4?.())
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran = agentMember({
    member: 'Carousel',
    element: () => root,
    state: () => ({
      index: shown,
      slides: slides.map((slide) => ({ id: slide.id, label: slide.label })),
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!Number.isInteger(value) || value < 0 || value >= slides.length) {
              throw new Error(
                `There is no slide ${value}; the slides run from 0 to ${slides.length - 1}.`,
              )
            }
            travel(value)
          })(),
      },
    },
    withholds: () => controls,
  })
  release5 = () => {
    ran()
  }
}
watchEffect(effect5)
onDestroy(() => release5?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if slides.length > 0
    }<section
      bind:this={root}
      role="group"
      aria-roledescription={roleDescriptions.carousel}
      aria-label={label}
      data-member="carousel"
      ><div
        bind:this={viewport}
        {...attributes(mergeParts({ ...api.getItemGroupProps(), style: undefined, dir: undefined }, { onScroll: () => { scrolls += 1 } }))}
        class={styles.viewport}
        tabindex="0"
        role="region"
        aria-label={label}
        aria-live={undefined}
        >{#each slides as slide, at (slide.id)
          }<div
            {...attributes({ ...api.getItemProps({ index: at }), style: undefined, dir: undefined })}
            class={styles.slide}
            role="group"
            aria-roledescription={roleDescriptions.slide}
            aria-label={slide.label}
            aria-hidden={undefined}
            >{#if typeof slide.content === 'string'
              }{slide.content
            }{:else
              }<Render node={slide.content}
            />{/if
          }</div
        >{/each
      }</div
      ><div bind:this={controls} class={styles.controls}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          iconOnly={true}
          icon="previous"
          label={previousLabel}
          disabled={!loop && shown === 0}
          onClick={() => { travel(shown === 0 ? slides.length - 1 : shown - 1) }}
        /><span class={styles.rail}
          >{#each slides as slide, at (slide.id)
            }<button
              class={styles.dot}
              type="button"
              data-carousel-part="dot"
              aria-label={slide.label}
              aria-current={(at === shown) ? true : undefined}
              onclick={() => { travel(at) }}
            ></button
          >{/each
        }</span
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          iconOnly={true}
          icon="next"
          label={nextLabel}
          disabled={!loop && shown === slides.length - 1}
          onClick={() => { travel(shown === slides.length - 1 ? 0 : shown + 1) }}
      /></div
    ></section
  >{/if
}{/if
}{@render joined.end?.()}
